def find_word_occurances_in_text(text, word):
    count = 0
    previous_index = 0

    while True:
        index = text.find(word, previous_index)

        if index == -1:
            break

        count += 1
        previous_index = index + 1
    
    return count

def valid_english_words_count(text):
    count = 0
    with open("common.txt", "r") as file:
        content = file.read()
        lines = content.split("\n")
        for line in lines:
            count += find_word_occurances_in_text(text, line.strip(" \n"))
    
    return count

